INSERT INTO public.items (id, user_id, item_type, item_name, category_id, description, brand, color, identifying_features, item_date, item_time, location, image_url, status, verification_status, is_demo, created_at)
VALUES
  ('22222222-2222-4222-8222-222222222201','11111111-1111-4111-8111-111111111101','lost','Black Samsung Galaxy M34',(SELECT id FROM public.categories WHERE name='Mobile Phone'),'Lost my phone somewhere between the IT block and the central library. It has a transparent back cover.','Samsung','Black','Cracked top-right corner of the screen protector, transparent cover with a sticker','2026-09-14','16:30','IT Block Corridor, Ground Floor','https://images.unsplash.com/photo-1511707171634-5f897ff02aa9?w=800&q=80','approved','approved',true, now() - interval '9 days'),
  ('22222222-2222-4222-8222-222222222202','11111111-1111-4111-8111-111111111102','found','Blue College ID Card',(SELECT id FROM public.categories WHERE name='ID Card'),'Found an ID card near the canteen counter. Handed a photo to the admin for verification.',NULL,'Blue','Lanyard has a small keyring attached','2026-09-16','13:10','Main Canteen','https://images.unsplash.com/photo-1586281380349-632531db7ed4?w=800&q=80','approved','approved',true, now() - interval '7 days'),
  ('22222222-2222-4222-8222-222222222203','11111111-1111-4111-8111-111111111103','found','Brown Leather Wallet',(SELECT id FROM public.categories WHERE name='Wallet'),'A brown wallet was found on a bench outside the seminar hall. Contains cards, no cash removed.','Woodland','Brown','Small tear on the inner card slot, metro card inside','2026-09-17','11:45','Seminar Hall Entrance','https://images.unsplash.com/photo-1627123424574-724758594e93?w=800&q=80','approved','approved',true, now() - interval '6 days'),
  ('22222222-2222-4222-8222-222222222204','11111111-1111-4111-8111-111111111104','lost','Dell Laptop Charger',(SELECT id FROM public.categories WHERE name='Laptop'),'Left my 65W laptop charger plugged in at the lab workstation number 12.','Dell','Black','Blue insulation tape wrapped near the adapter brick','2026-09-18','17:00','Computer Lab 2','https://images.unsplash.com/photo-1588872657578-7efd1f1555ed?w=800&q=80','approved','approved',true, now() - interval '5 days'),
  ('22222222-2222-4222-8222-222222222205','11111111-1111-4111-8111-111111111105','found','Set of Keys with Red Tag',(SELECT id FROM public.categories WHERE name='Keys'),'Three keys on a ring with a red plastic tag, found in the library reading room.',NULL,'Silver','Red tag with the number 214 written in marker','2026-09-19','10:20','Central Library, Reading Room','https://images.unsplash.com/photo-1582139329536-e7284fece509?w=800&q=80','approved','approved',true, now() - interval '4 days'),
  ('22222222-2222-4222-8222-222222222206','11111111-1111-4111-8111-111111111101','found','Black Boat Earphones',(SELECT id FROM public.categories WHERE name='Electronics'),'Wireless neckband earphones found in the shuttle bus.','boAt','Black','Left earbud has a small white paint mark','2026-09-20','18:40','Campus Shuttle Bay','https://images.unsplash.com/photo-1505740420928-5e560c06d30e?w=800&q=80','approved','approved',true, now() - interval '3 days'),
  ('22222222-2222-4222-8222-222222222207','11111111-1111-4111-8111-111111111102','lost','Engineering Mathematics Textbook',(SELECT id FROM public.categories WHERE name='Books'),'Third semester maths textbook with my name written on the first page.',NULL,'Green','Name "Rahul V" written on the first page, yellow sticky notes inside','2026-09-21','09:15','Lecture Hall 3','https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&q=80','approved','approved',true, now() - interval '2 days'),
  ('22222222-2222-4222-8222-222222222208','11111111-1111-4111-8111-111111111103','found','Grey Hoodie',(SELECT id FROM public.categories WHERE name='Clothing'),'Hoodie left behind in the sports complex changing area.','H&M','Grey','Small ink stain on the right sleeve','2026-09-21','19:05','Sports Complex','https://images.unsplash.com/photo-1556821840-3a63f95609a7?w=800&q=80','approved','approved',true, now() - interval '2 days'),
  ('22222222-2222-4222-8222-222222222209','11111111-1111-4111-8111-111111111104','lost','Silver Wrist Watch',(SELECT id FROM public.categories WHERE name='Accessories'),'Lost my watch during the inter-department football match.','Titan','Silver','Scratch on the dial glass near the 6 o clock mark','2026-09-22','15:50','Football Ground','https://images.unsplash.com/photo-1524592094714-0f0654e20314?w=800&q=80','pending','pending',true, now() - interval '1 day'),
  ('22222222-2222-4222-8222-222222222210','11111111-1111-4111-8111-111111111105','found','Blue Water Bottle',(SELECT id FROM public.categories WHERE name='Other'),'Steel water bottle found at the admin block reception.','Milton','Blue','Dent near the base, small cartoon sticker','2026-09-22','12:00','Admin Block Reception','https://images.unsplash.com/photo-1602143407151-7111542de6e8?w=800&q=80','pending','pending',true, now() - interval '1 day'),
  ('22222222-2222-4222-8222-222222222211','11111111-1111-4111-8111-111111111101','found','Scientific Calculator',(SELECT id FROM public.categories WHERE name='Electronics'),'Casio calculator found in exam hall B after the internal assessment.','Casio','Black','Roll number 21IT045 written on the back with marker','2026-09-10','17:30','Exam Hall B','https://images.unsplash.com/photo-1587145820266-a5951ee6f620?w=800&q=80','recovered','approved',true, now() - interval '13 days'),
  ('22222222-2222-4222-8222-222222222212','11111111-1111-4111-8111-111111111102','found','Spiral Notebook with Notes',(SELECT id FROM public.categories WHERE name='Documents'),'Notebook with DBMS notes found in the department office.',NULL,'Orange','Cover has a hand-drawn logo','2026-09-08','14:25','IT Department Office','https://images.unsplash.com/photo-1531346878377-a5be20888e57?w=800&q=80','recovered','approved',true, now() - interval '15 days')
INSERT INTO public.claims (id, item_id, claimant_id, reason, proof_description, lost_date, lost_location, status, admin_remarks, is_demo, created_at) VALUES
  ('33333333-3333-4333-8333-333333333301','22222222-2222-4222-8222-222222222203','11111111-1111-4111-8111-111111111105','The wallet matches the one I lost the same afternoon near the seminar hall.','Brown Woodland wallet with a torn inner card slot and a metro card inside.','2026-09-17','Seminar Hall','pending',NULL,true, now() - interval '5 days'),
  ('33333333-3333-4333-8333-333333333302','22222222-2222-4222-8222-222222222211','11111111-1111-4111-8111-111111111104','My roll number is written on the back of that calculator.','Roll number 21IT045 written in black marker on the rear panel.','2026-09-10','Exam Hall B','approved','Roll number verified against student records. Item handed over at the admin desk.',true, now() - interval '12 days'),
  ('33333333-3333-4333-8333-333333333303','22222222-2222-4222-8222-222222222205','11111111-1111-4111-8111-111111111102','I lost my hostel keys with a red tag on the same day.','Red tag with 214 written on it, three keys on a single ring.','2026-09-19','Library','under_review','Waiting for the claimant to show the hostel allotment slip.',true, now() - interval '3 days')
